"""All five official FAQ tables, transparent date normalization and every explanation."""
PATTERN = ('Home Town','Home Town','Home Town','Any Place in India','Home Town','Home Town','Home Town','Any Place in India')

def sequence(first):
    return [(f'1 January {year} – 31 December {year}',kind,str(i)) for i,(year,kind) in enumerate(zip(range(first,first+8),PATTERN),1)]

